/**
 * THROWAWAY diagnostic — not part of the feature. Proves at runtime that
 * `useMultiStyleConfig('ZimmCartItem', {})` / `useMultiStyleConfig('ZimmCartItemVariant', {})`
 * resolve non-empty style objects under the REAL composed theme (overrides/app/theme/index.ts),
 * rather than tracing the composition chain by reading files only. Deleted immediately after use.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import { ChakraProvider, useMultiStyleConfig } from '@chakra-ui/react';
import theme from '../index';

let lastRow: unknown;
let lastVariant: unknown;

const CartItemProbe = () => {
  const styles = useMultiStyleConfig('ZimmCartItem', {});
  lastRow = styles;
  return null;
};

const CartItemVariantProbe = () => {
  const styles = useMultiStyleConfig('ZimmCartItemVariant', {});
  lastVariant = styles;
  return null;
};

describe('THROWAWAY wiring proof', () => {
  test('ZimmCartItem resolves non-empty row/details/info parts from the real theme', () => {
    render(
      <ChakraProvider theme={theme}>
        <CartItemProbe />
      </ChakraProvider>,
    );
    // eslint-disable-next-line no-console
    console.log('ZimmCartItem RESOLVED:', JSON.stringify(lastRow, null, 2));
    const s = lastRow as Record<string, Record<string, unknown>>;
    expect(s.row).toBeDefined();
    expect(s.details).toBeDefined();
    expect(s.info).toBeDefined();
    expect(Object.keys(s.row).length).toBeGreaterThan(0);
    expect(Object.keys(s.details).length).toBeGreaterThan(0);
    expect(Object.keys(s.info).length).toBeGreaterThan(0);
    // Specific values from product-item.css.ts's baseStyle, to prove this isn't an
    // accidental non-empty object from something else (e.g. base SFCC deep-merge noise).
    expect(s.row.gap).toBe('var(--zimm-scale-xl)');
    expect(s.info.justifyContent).toBe('space-between');
  });

  test('ZimmCartItemVariant resolves non-empty image/img/colourSize/price parts from the real theme', () => {
    render(
      <ChakraProvider theme={theme}>
        <CartItemVariantProbe />
      </ChakraProvider>,
    );
    // eslint-disable-next-line no-console
    console.log('ZimmCartItemVariant RESOLVED:', JSON.stringify(lastVariant, null, 2));
    const s = lastVariant as Record<string, Record<string, unknown>>;
    expect(s.image).toBeDefined();
    expect(s.img).toBeDefined();
    expect(s.colourSize).toBeDefined();
    expect(s.price).toBeDefined();
    expect(Object.keys(s.image).length).toBeGreaterThan(0);
    expect(Object.keys(s.img).length).toBeGreaterThan(0);
    expect(Object.keys(s.colourSize).length).toBeGreaterThan(0);
    expect(Object.keys(s.price).length).toBeGreaterThan(0);
    expect(s.image.width).toBe('67px');
    expect(s.colourSize.width).toBe('200px');
    expect(s.price.textStyle).toBe('price');
  });
});

