/**
 * THROWAWAY diagnostic — empirically verifies a specific claim about Chakra's real, installed
 * `Flex` component: does a caller-supplied `__css` prop get "outranked" by Flex's own computed
 * `display:"flex"` default (per-key merge), or does it wholesale replace Flex's own style object
 * (JS object-literal same-key-last-wins)? Deleted immediately after use.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import { ChakraProvider, Flex } from '@chakra-ui/react';
import theme from '../index';

describe('THROWAWAY Flex __css proof', () => {
  test('a caller-supplied __css prop wholesale replaces Flex own display:flex default (not outranked)', () => {
    const { container } = render(
      <ChakraProvider theme={theme}>
        <Flex __css={{ flexDirection: 'row', gap: '24px' }} data-testid="probe" />
      </ChakraProvider>,
    );
    const el = container.querySelector('[data-testid="probe"]') as HTMLElement;
    const computed = window.getComputedStyle(el);
    // eslint-disable-next-line no-console
    console.log('Flex __css-only computed display:', computed.display, '| flexDirection:', computed.flexDirection, '| gap:', computed.gap);
    // If Flex's own {display:"flex", ...} object were merely "outranked" per key (i.e. the
    // caller's __css only lost individual keys like alignItems to Flex's own), display would
    // still read 'flex' because Flex always sets it and the caller's __css never mentioned
    // 'display' at all, so there'd be nothing to lose that key to.
    // If instead the caller's __css wholesale REPLACES Flex's own object (object-literal
    // same-key overwrite), display reverts to the browser default 'block' because Flex's own
    // display:"flex" never reaches the DOM at all.
    expect(computed.display).not.toBe('flex');
    expect(computed.flexDirection).toBe('row');
  });

  test('control: Flex with no __css override at all still defaults to display:flex', () => {
    const { container } = render(
      <ChakraProvider theme={theme}>
        <Flex data-testid="control" />
      </ChakraProvider>,
    );
    const el = container.querySelector('[data-testid="control"]') as HTMLElement;
    const computed = window.getComputedStyle(el);
    // eslint-disable-next-line no-console
    console.log('Flex control (no __css) computed display:', computed.display);
    expect(computed.display).toBe('flex');
  });
});

