/**
 * THROWAWAY diagnostic — does jsdom/Vitest actually surface a Text `__css`-discard bug via
 * getComputedStyle, or would it silently pass? Deleted immediately after use.
 */
import React from 'react';
import { describe, test, expect } from 'vitest';
import { render } from '@testing-library/react';
import { ChakraProvider, Text } from '@chakra-ui/react';
import theme from '../index';

describe('THROWAWAY Text __css vs sx proof under jsdom', () => {
  test('__css on Text is discarded (computed color stays default, not red) — visible under jsdom', () => {
    const { getByTestId } = render(
      <ChakraProvider theme={theme}>
        <Text data-testid="viaCss" __css={{ color: 'red' }}>
          hi
        </Text>
      </ChakraProvider>,
    );
    const computed = window.getComputedStyle(getByTestId('viaCss'));
    // eslint-disable-next-line no-console
    console.log('Text __css={color:red} computed color under jsdom:', computed.color);
    expect(computed.color).not.toBe('red');
  });

  test('sx on Text is honoured (computed color IS red) — visible under jsdom', () => {
    const { getByTestId } = render(
      <ChakraProvider theme={theme}>
        <Text data-testid="viaSx" sx={{ color: 'red' }}>
          hi
        </Text>
      </ChakraProvider>,
    );
    const computed = window.getComputedStyle(getByTestId('viaSx'));
    // eslint-disable-next-line no-console
    console.log('Text sx={color:red} computed color under jsdom:', computed.color);
    expect(computed.color).toBe('red');
  });
});

